// Native half of clipboard_history.rs on macOS: the pasteboard change counter,
// the privacy markers password managers set, reading and writing copied
// images, and the paste into the app the user was in before the picker opened.
#import <AppKit/AppKit.h>
#import <Carbon/Carbon.h>

long clipy_pasteboard_change_count(void) {
  @autoreleasepool {
    return (long)[[NSPasteboard generalPasteboard] changeCount];
  }
}

// nspasteboard.org markers. Password managers set Concealed; Transient and
// AutoGenerated mark content the source app says is not worth keeping.
int clipy_pasteboard_is_private(void) {
  @autoreleasepool {
    NSArray<NSPasteboardType> *types = [[NSPasteboard generalPasteboard] types];
    for (NSString *marker in @[
           @"org.nspasteboard.ConcealedType",
           @"org.nspasteboard.TransientType",
           @"org.nspasteboard.AutoGeneratedType",
           @"com.agilebits.onepassword",
         ]) {
      if ([types containsObject:marker]) return 1;
    }
    return 0;
  }
}

// Whether a PNG's header (its IHDR chunk) gives a size of at most max_pixels,
// read before anything is copied or decoded.
static int png_fits(NSData *png, uint64_t max_pixels) {
  static const uint8_t signature[8] = {0x89, 'P', 'N', 'G', '\r', '\n', 0x1a, '\n'};
  if (png.length < 24) return 0;
  const uint8_t *b = png.bytes;
  if (memcmp(b, signature, sizeof signature) != 0) return 0;
  uint64_t width = ((uint32_t)b[16] << 24) | ((uint32_t)b[17] << 16) | ((uint32_t)b[18] << 8) | b[19];
  uint64_t height = ((uint32_t)b[20] << 24) | ((uint32_t)b[21] << 16) | ((uint32_t)b[22] << 8) | b[23];
  return width > 0 && height > 0 && width * height <= max_pixels;
}

// The copied image as PNG bytes, or NULL when the pasteboard holds none.
// PNG data is taken as it is, so a Retina screenshot keeps its resolution;
// TIFF (what most apps put up) is converted. Either way an image of more
// than max_pixels is refused before it is copied. A copied file is not an
// image here even when Finder adds its icon. The caller frees with clipy_free.
uint8_t *clipy_pasteboard_image_png(size_t *len, uint64_t max_pixels) {
  @autoreleasepool {
    *len = 0;
    NSPasteboard *board = [NSPasteboard generalPasteboard];
    NSArray<NSPasteboardType> *types = [board types];
    if ([types containsObject:NSPasteboardTypeFileURL]) return NULL;
    NSData *png = [board dataForType:NSPasteboardTypePNG];
    if (png.length > 0 && !png_fits(png, max_pixels)) return NULL;
    if (png.length == 0) {
      NSData *tiff = [board dataForType:NSPasteboardTypeTIFF];
      if (tiff.length == 0) return NULL;
      NSBitmapImageRep *rep = [NSBitmapImageRep imageRepWithData:tiff];
      if (rep.pixelsWide <= 0 || rep.pixelsHigh <= 0 ||
          (uint64_t)rep.pixelsWide * (uint64_t)rep.pixelsHigh > max_pixels) {
        return NULL;
      }
      png = [rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}];
    }
    if (png.length == 0) return NULL;
    uint8_t *out = malloc(png.length);
    if (!out) return NULL;
    memcpy(out, png.bytes, png.length);
    *len = png.length;
    return out;
  }
}

void clipy_free(void *ptr) { free(ptr); }

// Puts a history image back as PNG, with TIFF beside it for the apps that
// only read that, and the text that was copied with it (text may be NULL).
// 1 on success.
int clipy_pasteboard_write_png(const uint8_t *bytes, size_t len, const char *text) {
  @autoreleasepool {
    NSData *png = [NSData dataWithBytes:bytes length:len];
    NSBitmapImageRep *rep = [NSBitmapImageRep imageRepWithData:png];
    NSData *tiff = [rep TIFFRepresentation];
    NSPasteboard *board = [NSPasteboard generalPasteboard];
    [board clearContents];
    BOOL ok = [board setData:png forType:NSPasteboardTypePNG];
    if (ok && tiff.length > 0) [board setData:tiff forType:NSPasteboardTypeTIFF];
    NSString *string = text ? [NSString stringWithUTF8String:text] : nil;
    if (ok && string.length > 0) [board setString:string forType:NSPasteboardTypeString];
    return ok ? 1 : 0;
  }
}

int clipy_frontmost_pid(void) {
  @autoreleasepool {
    NSRunningApplication *app = [[NSWorkspace sharedWorkspace] frontmostApplication];
    return app ? (int)app.processIdentifier : 0;
  }
}

int clipy_activate_pid(int pid) {
  @autoreleasepool {
    NSRunningApplication *app = [NSRunningApplication runningApplicationWithProcessIdentifier:pid];
    if (!app) return 0;
#pragma clang diagnostic push
#pragma clang diagnostic ignored "-Wdeprecated-declarations"
    return [app activateWithOptions:NSApplicationActivateIgnoringOtherApps] ? 1 : 0;
#pragma clang diagnostic pop
  }
}

// Synthetic ⌘V. Needs the Accessibility permission Clipy already asks for;
// without it the event is dropped and the item is only on the clipboard.
void clipy_post_paste(void) {
  CGEventSourceRef source = CGEventSourceCreate(kCGEventSourceStateCombinedSessionState);
  CGEventRef down = CGEventCreateKeyboardEvent(source, (CGKeyCode)kVK_ANSI_V, true);
  CGEventRef up = CGEventCreateKeyboardEvent(source, (CGKeyCode)kVK_ANSI_V, false);
  CGEventSetFlags(down, kCGEventFlagMaskCommand);
  CGEventSetFlags(up, kCGEventFlagMaskCommand);
  CGEventPost(kCGAnnotatedSessionEventTap, down);
  CGEventPost(kCGAnnotatedSessionEventTap, up);
  CFRelease(up);
  CFRelease(down);
  if (source) CFRelease(source);
}

int clipy_app_is_running(const char *bundle_id) {
  @autoreleasepool {
    NSString *identifier = [NSString stringWithUTF8String:bundle_id];
    if (!identifier) return 0;
    return [NSRunningApplication runningApplicationsWithBundleIdentifier:identifier].count > 0 ? 1 : 0;
  }
}
